/**
 * Release data for Anvira, Anvira Notes and Anvira Runtime.
 *
 * Generated by scripts/sync-releases.mjs from the GitHub release repos — do not
 * edit the JSON by hand. A scheduled GitHub Action re-runs the sync and commits
 * any change, so versions, sizes, checksums and notes on the site follow each
 * new release without code changes.
 */
import summary from './releases-summary.json';

export type ProductId = 'anvira-notes' | 'anvira' | 'anvira-runtime';

export interface Installer {
  name: string;
  size: number;
  url: string;
  sha256: string | null;
}

export interface Highlight {
  kind: string;
  text: string;
}

export interface ReleaseSummary {
  tag: string;
  version: string;
  name: string;
  date: string;
  url: string;
  latest: boolean;
  installer: Installer | null;
  summary: string;
  highlights: Highlight[];
  /** In the summary file only the latest release of each product carries its notes. */
  notes?: ReleaseNoteSection[];
}

export interface ReleaseNoteSection {
  title: string;
  html: string;
}

export interface Release extends ReleaseSummary {
  notes: ReleaseNoteSection[];
}

export interface Product<R extends ReleaseSummary = ReleaseSummary> {
  id: ProductId;
  name: string;
  repo: string;
  page: string;
  releasesUrl: string;
  latest: string | null;
  releases: R[];
}

export const releaseProducts = summary.products as Product[];
export const releasesSyncedAt = summary.syncedAt;

export const getProduct = (id: ProductId) => releaseProducts.find((p) => p.id === id)!;

/** The release GitHub marks as "Latest" (not simply the newest by date). */
export const latestRelease = (id: ProductId): ReleaseSummary => {
  const p = getProduct(id);
  return p.releases.find((r) => r.tag === p.latest) ?? p.releases[0];
};

/** Most recent headline features across recent releases ("New" items first). */
export const recentHighlights = (id: ProductId, count = 4, releases = 6) => {
  const recent = getProduct(id).releases.slice(0, releases);
  const pick = (kinds: RegExp) =>
    recent.flatMap((r) => r.highlights.filter((h) => kinds.test(h.kind)).map((h) => ({ ...h, version: r.version })));
  const seen = new Set<string>();
  return [...pick(/^new$/i), ...pick(/^(changed|better|faster)$/i), ...pick(/./)]
    .filter((h) => !seen.has(h.text) && seen.add(h.text))
    .slice(0, count);
};

export const releaseAnchor = (productId: ProductId, version: string) => `${productId}-${version.replace(/\./g, '-')}`;

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

/** "13 October 2026" — formatted from the UTC date so prerendered and hydrated HTML match. */
export const formatReleaseDate = (iso: string) => {
  const d = new Date(iso);
  return `${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
};

export const isoDay = (iso: string) => iso.slice(0, 10);

export const formatSize = (bytes: number) =>
  bytes >= 1e9 ? `${(bytes / 1e9).toFixed(1)} GB` : bytes >= 1e6 ? `${Math.round(bytes / 1e6)} MB` : `${Math.round(bytes / 1e3)} KB`;
